const window = new Map();          // seq -> message, arrived out of order
let expected = 1, gapTimer;
function accept(seq, msg, deliver, gapMs) {
  window.set(seq, msg);            // duplicates policy: keep last
  while (window.has(expected)) {
    deliver(window.get(expected));
    window.delete(expected++);     // the contiguous run leaves in order
  }
  clearTimeout(gapTimer);          // re-arm the deadline for the hole
  gapTimer = setTimeout(() => { window.delete(expected++); }, gapMs);
}
